\centering
\small
\begin{tabular}{@{}lccc@{}}
\toprule
 & uniform & parabola & collision \\
 & (both-OOD) & (\rmood) & (both-OOD) \\
\midrule
Free-rollout baseline & $0.131$ & $0.127$ & $0.393$ \\
\midrule
Fixed slot (weight $1$) & $0.183$ & $^{\ddagger}$ & $^{\ddagger}$ \\
Fixed slot $+$ LBR & $0.114$ & $0.160$ & $0.596$ \\
Probe ($\lambda{=}1$, $K{=}2$) & $0.167$ & $^{\ddagger}$ & $^{\ddagger}$ \\
