\begin{tabular}{@{}lccc@{}}
\toprule
 & teacher forcing & free rollout & gain \\
\midrule
uniform & $0.300\pm0.006$ & $\mathbf{0.136\pm0.007}$ & $2.2\times$ \\
parabola (\rmood) & $0.443\pm0.047$ & $\mathbf{0.122\pm0.006}$ & $3.6\times$ \\
